class PlanetBase extends Component {
  constructor(props) {
    super(props);

    const [px = 0, py = 0, pz = 0] = props.position || [];
    this._rawPosition = new THREE.Vector3(px, py, pz);

    this._position = new Proxy(this._rawPosition, {
      get: (target, prop) => target[prop],
      set: (target, prop, value) => {
        if (["x", "y", "z"].includes(prop)) {
          target[prop] = value;
          this.forceUpdate();
          return true;
        }
        return Reflect.set(target, prop, value);
      }
    });

    this._rotation = props.rotation ?? [0, 0, 0];
    this._sunPosition = props.sunPosition ?? [10, 10, 5];
    this.args = props.args || [20, 30, 30];
    this.state = { hover: false };
    this.ref = createRef();
    this.atmosphereRef = createRef();
  }

  get position() {
    return this._position;
  }

  set position(value){
    this._position = value;
  }


  componentDidMount(){
    this.atmosphereRef.current.sunPosition = [0, 50, 100]
  }

  // Expose the inner mesh ref so PlanetGroup can drive animation
  getMeshRef() {
    return this.ref;
  }

  handleHover = () => {
    this.setState((prevState) => ({ hover: !prevState.hover }));
  };

  render() {
    return (
      <AtmospherePass ref={this.atmosphereRef}>
          <mesh
            ref={this.ref}
            material={this.props.material}
            position={[this._position.x, this._position.y, this._position.z]}
            rotation={this._rotation}
            castShadow
            receiveShadow
            onPointerEnter={this.handleHover}
            onPointerLeave={this.handleHover}
            userData={{sunPosition: this._sunPosition}}
          >
            <sphereGeometry args={this.args} />
          </mesh>
      </AtmospherePass>

    );
  }
}


const STELLAR_CLASSES = [
  // { type, kelvin range, RGB color, weight (higher = more common) }
  // Colors are white-blended for brightness: lerped ~60% toward (255,255,255)
  { type: "O", kelvinMin: 30000, kelvinMax: 50000, r: 220, g: 228, b: 255, weight: 0.00003 }, // Blue-white
  { type: "B", kelvinMin: 10000, kelvinMax: 30000, r: 222, g: 230, b: 255, weight: 0.13   }, // Blue-white
  { type: "A", kelvinMin:  7500, kelvinMax: 10000, r: 235, g: 240, b: 255, weight: 0.6    }, // Near-white
  { type: "F", kelvinMin:  6000, kelvinMax:  7500, r: 252, g: 251, b: 255, weight: 3      }, // White with faint yellow
  { type: "G", kelvinMin:  5200, kelvinMax:  6000, r: 255, g: 252, b: 235, weight: 7      }, // Warm white
  { type: "K", kelvinMin:  3700, kelvinMax:  5200, r: 255, g: 235, b: 210, weight: 12     }, // Pale orange-white
  { type: "M", kelvinMin:  2400, kelvinMax:  3700, r: 255, g: 228, b: 190, weight: 76     }, // Warm white-orange
];

// Precompute cumulative weights for weighted random selection
const totalWeight = STELLAR_CLASSES.reduce((sum, c) => sum + c.weight, 0);
const cumulativeWeights = [];
let cumSum = 0;
for (const cls of STELLAR_CLASSES) {
  cumSum += cls.weight;
  cumulativeWeights.push(cumSum / totalWeight);
}



function pickStellarClass() {
  const r = Math.random();
  for (let i = 0; i < cumulativeWeights.length; i++) {
    if (r <= cumulativeWeights[i]) return STELLAR_CLASSES[i];
  }
  return STELLAR_CLASSES[STELLAR_CLASSES.length - 1];
}

class StarMaterial extends THREE.ShaderMaterial {
  constructor() {
    super({
      uniforms: {
        streakLength: { value: 12.0 },
      },
      vertexShader: `
        attribute vec3 color;
        attribute float size;
        attribute float angle;
        varying vec3 vColor;
        attribute vec3 direction;
        varying vec3 vDirection;

        void main() {
          vColor = color;
          vDirection = normalize((projectionMatrix * vec4(direction, 0.0)).xyz);

          vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (300.0 / -mvPosition.z);
          gl_Position = projectionMatrix * mvPosition;
        }
      `,
      fragmentShader: `
        uniform float streakLength;
        varying vec3 vColor;
        varying vec3 vDirection;

        void main() {
          vec2 uv = gl_PointCoord - vec2(0.5);

          // Project the 3D view-space direction onto the 2D billboard
          vec2 dir  = normalize(vDirection.xy);
          vec2 perp = vec2(-dir.y, dir.x);

          float along  = dot(uv, dir);
          float across = dot(uv, perp);

          float stretchedAlong = along  / streakLength;
          float squeezedAcross = across * streakLength;

          float ellipse = stretchedAlong * stretchedAlong + squeezedAcross * squeezedAcross;
          if (ellipse > 0.25) discard;

          float alpha = 1.0 - smoothstep(0.0, 0.25, ellipse);
          alpha = pow(alpha, 1.2);

          gl_FragColor = vec4(vColor, alpha);
        }
      `,
      transparent: true,
    });
  }
}

extend({ StarMaterial });

class Star {
    constructor(x, y, z, ctx) {
        this.Y = 50;

        this.ctx = ctx;

        this.pos     = new THREE.Vector3(x, y, z);
        this.prevPos =  new THREE.Vector3(x, y, z);
        this.pointPos = new THREE.Vector3(0, 0, 0);

        this.vel = { x: 0, y: 0 , z: 0};

        // // 2D angle from camera XY position to star XY position
        //   this.cameraPos = new THREE.Vector3(camX, 50, camZ); // your predefined Y


          // 3D direction from camera to star
        this.dir = new THREE.Vector3().subVectors(this.pos, this.pointPos).normalize();

        // this.ang = Math.atan2(
        //     y - height / 2,
        //     x - width / 2,
        //     z - depth / 2,
        // );

        this.z3d  = 0;
        this.size = Math.random() * .75 + 0.5;
        this.alpha = 0;

        // Assign stellar classification by rarity-weighted random
        const cls = pickStellarClass();
        this.r = cls.r;
        this.g = cls.g;
        this.b = cls.b;


        // O and B type stars are brighter/larger
        if (cls.type === "O") {
            this.size = Math.random() * 2.5 + 1.5;
        } else if (cls.type === "B") {
            this.size = Math.random() * 2.0 + 1.0;
        }
    }
}

const NUM_STARS = 1000;


// Shared geometry and dummy for matrix computation
const _starGeometry = new THREE.PlaneGeometry(1, 1);
const _dummy = new THREE.Object3D();
const _color = new THREE.Color();

export class Stars extends Component {
  constructor(props) {
    super(props);

    this.meshRef = createRef();
    this.camera = props.camera;

    this.stars = Array.from({ length: NUM_STARS }, () => new Star(
      this.random(-600, 600),
      this.random(-400, 400),
      this.random(-150, 0),
      null,
    ));

    // Build instanced mesh
    const material = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      vertexColors: true,
    });


      this.instancedMesh = new THREE.InstancedMesh(_starGeometry, material, NUM_STARS);
      this.instancedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

      // Initialize instanceColor buffer BEFORE setColorAt
      this.instancedMesh.instanceColor = new THREE.InstancedBufferAttribute(
        new Float32Array(NUM_STARS * 3),
        3
      );

      this.stars.forEach((star, i) => {
        _dummy.position.copy(star.pos);
        _dummy.scale.setScalar(star.size);
        _dummy.updateMatrix();
        this.instancedMesh.setMatrixAt(i, _dummy.matrix);

        _color.setRGB(star.r / 255, star.g / 255, star.b / 255);
        this.instancedMesh.setColorAt(i, _color);
      });

      this.instancedMesh.instanceMatrix.needsUpdate = true;
      this.instancedMesh.instanceColor.needsUpdate = true;
  }

  random(min, max) { return Math.random() * (max - min) + min; }

  render() {
    return <primitive object={this.instancedMesh} ref={this.meshRef} />;
  }
}
class PlanetGroup extends Component {
  constructor(props) {
    super(props);

    this.groupRef = createRef();
    this.lightRef = createRef();
    this.planetRef = createRef();
    this.atmosphereRef = createRef();
    this.pathRef = createRef();

    this.material = this.initMaterial(); // ← call it, fix typo

    this.currentT = 0;
    this.targetT = 0;

    this.targetPoint = new THREE.Vector3();

    // this.handleScroll = this.handleScroll.bind(this);
  }

  initMaterial() {
    const loader = new THREE.TextureLoader();

    const dif    = loader.load(Diffuse.src,  (texture) => this.setState({ diffuseMap:  texture }));
    const bump   = loader.load(Bump.src,     (texture) => this.setState({ bumpMap:     texture }));
    const spec   = loader.load(Specular.src, (texture) => this.setState({ specularMap: texture }));
    const lights = loader.load(Lights.src,   (texture) => this.setState({ lightsMap:   texture }));

    return new SolidPlanetMaterial({ // ← return the material
      map: dif,
      bumpMap: bump,
      bumpScale: 0.5,
      specularIntensityMap: spec,
      lightMap: lights,
    });
  }

  componentDidMount() {
    window.addEventListener("scroll", this.handleScroll, { passive: true });
    this.currentT = 0;
    this.targetT = 0;
    this.animate();
  }

  componentWillUnmount() {
    window.removeEventListener("scroll", this.handleScroll);
    if (this.rafId) cancelAnimationFrame(this.rafId);
  }

  animate() {
    this.rafId = requestAnimationFrame(() => this.animate());

    const mesh = this.planetRef.current?.ref?.current;
    if (!mesh) return;

    mesh.rotation.x += 0.0001;
  }


  render() {
    return (
      <>
        <group ref={this.groupRef}>
          <directionalLight
            ref={this.lightRef}
            position={[0, 50, 100]}
            castShadow
            intensity={4.0}
            shadow-mapSize-width={1024}
            shadow-mapSize-height={1024}
            shadow-camera-far={50}
            shadow-camera-left={-10}
            shadow-camera-right={10}
            shadow-camera-top={10}
            shadow-camera-bottom={-10}
          />
          <mesh > 
            <sphereGeometry args={[2, 300, 300]} />
            <meshBasicMaterial color={"red"} />
          </mesh>
          <PlanetBase
            ref={this.planetRef}
            position={[2, 0, 0]}
            args={[20, 300, 300]}
            rotation={[0, 0, Math.PI / 2]}
            material={this.material} // ← reference via this
          />
          {/* <CurvedPath ref={this.pathRef}/> */}
        </group>
      </>
    );
  }
}

export default PlanetGroup;